import{_ as a,o as e,c as r,a3 as d}from"./chunks/framework.CVt6dz2a.js";const b=JSON.parse('{"title":"EP.30 把数字翻译成高度","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.30-numbers-to-height.md","filePath":"comics/EP.30-numbers-to-height.md","lastUpdated":1793881879000}'),o={name:"comics/EP.30-numbers-to-height.md"};function i(l,t,h,s,n,u){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="ep-30-把数字翻译成高度" tabindex="-1">EP.30 把数字翻译成高度 <a class="header-anchor" href="#ep-30-把数字翻译成高度" aria-label="Permalink to &quot;EP.30 把数字翻译成高度&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/30-data-visualization-3d/basics">30.1 基础入门：3D 图表的语法与数据映射</a> 延伸阅读：<a href="./../guide/30-data-visualization-3d/advanced">30.2 进阶应用：大规模数据、交互与标注</a> · <a href="./../guide/30-data-visualization-3d/practice">30.3 实战案例：可交互 3D 数据看板</a> 动手演示：<a href="./../public/demos/data-viz-3d/chart-mapping-lab.html">chart-mapping-lab 图表形态对比台</a> · <a href="./../public/demos/data-viz-3d/scatter-scale-lab.html">scatter-scale-lab 十万级散点</a> · <a href="./../public/demos/data-viz-3d/dashboard-lab.html">dashboard-lab 可交互看板</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱为了让差距&quot;更明显&quot;，把柱子从半空起算；标签君盯着画面问：这根柱子到底代表多少？</td></tr><tr><td>② 揭秘</td><td>码叔画出一张映射表：位置放维度、高度放数值、颜色放类别或大小；图表先有语法，才有装饰。</td></tr><tr><td>③ 实证</td><td>同一份数据切换柱状、散点、曲面，三种说法各有所长；3D 饼图被画上一个大叉。</td></tr><tr><td>④ 结案</td><td>三条纪律钉进看板：0 基线、分类色不超八种、3D 只在第三个维度真的有用时上场。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-高度不是数值-除非从-0-起算" tabindex="-1">① 高度不是数值，除非从 0 起算 <a class="header-anchor" href="#_1-高度不是数值-除非从-0-起算" aria-label="Permalink to &quot;① 高度不是数值，除非从 0 起算&quot;">​</a></h3><p>柱状图的长度只有在<strong>统一起点、统一比例尺</strong>下才与数值成正比。把基线抬到半空，视觉差距会被放大，但读者读出的倍数关系也随之失真。3D 柱状更要注意：透视会让远处柱子变短，没有 0 基线和网格时，读者会把&quot;近&quot;误当成&quot;高&quot;。</p><p>正确做法是三件事一起做：所有柱子从同一个 y=0 平面长出、共用同一个高度归一化比例、至少提供一条可换算的参考（刻度、网格或数值标签）。如果数据差距太小，改用差值、增长率或对数刻度并明确标注，而不是偷偷截断基线。</p><h3 id="_2-三种形态是三种句子" tabindex="-1">② 三种形态是三种句子 <a class="header-anchor" href="#_2-三种形态是三种句子" aria-label="Permalink to &quot;② 三种形态是三种句子&quot;">​</a></h3><table tabindex="0"><thead><tr><th>形态</th><th>主要编码</th><th>最擅长</th><th>最容易翻车</th></tr></thead><tbody><tr><td>3D 柱状</td><td>高度 = 数值</td><td>比大小、排名、同比</td><td>非 0 基线、遮挡、透视缩短</td></tr><tr><td>3D 散点</td><td>三个位置轴各放一个维度</td><td>相关、聚类、离群点</td><td>三轴含义不清、点云重叠</td></tr><tr><td>曲面高度图</td><td>高度 = 网格数值</td><td>整体趋势、波峰波谷</td><td>单点读数难、背面被遮挡</td></tr></tbody></table><p>柱状在比较离散个体，散点在寻找变量关系，曲面在描述连续场。选错形态，后面调再久也只是把一句话说错得更漂亮。</p><h3 id="_3-颜色是第四个通道-不是滤镜" tabindex="-1">③ 颜色是第四个通道，不是滤镜 <a class="header-anchor" href="#_3-颜色是第四个通道-不是滤镜" aria-label="Permalink to &quot;③ 颜色是第四个通道，不是滤镜&quot;">​</a></h3><p>颜色有三种基本用法：<strong>分类色</strong>表达无序类别，最多六到八种；<strong>连续色</strong>表达有序数值，明度或色相单向递进；<strong>发散色</strong>表达围绕中点的偏离，两端用对立色相。用彩虹渐变表达连续数值、用分类色表达有序数据，都是让颜色&quot;看起来有信息，实际读不出信息&quot;。</p><p>还要记住两条：颜色不能是唯一编码，必须配标签、形状或位置；色板的十六进制默认按 sRGB 解释，进入 Three.js 后会解码到线性工作空间，和色彩管理那一篇的链路保持一致。</p><h3 id="_4-3d-的门槛-第三个维度真的有用吗" tabindex="-1">④ 3D 的门槛：第三个维度真的有用吗 <a class="header-anchor" href="#_4-3d-的门槛-第三个维度真的有用吗" aria-label="Permalink to &quot;④ 3D 的门槛：第三个维度真的有用吗&quot;">​</a></h3><p>3D 适合三类场景：数据本身有三个空间维度、需要空间关系、展示与沉浸优先于精确读数。如果问题只是&quot;谁最高、谁最低&quot;，2D 柱状永远更快更准。3D 饼图是反模式的代表：倾斜让角度被透视压缩，遮挡让扇区消失，读者几乎无法比较占比。</p><p>判断标准不是&quot;好不好看&quot;，而是&quot;第三个维度是不是问题的一部分&quot;。不是，就别加；是，就保证 0 基线、可读标签和正面视角都在。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：柱子差距很小，看不出来？</strong> 先切正面视角、打开 0 基线；仍看不清就改用差值、增长率或对数刻度，别截断基线。</li><li><strong>Q：分类色能用几种？</strong> 六到八种是经验上限；超过就合并长尾类别、分组或分面，并始终配标签。</li><li><strong>Q：曲面为什么不能报精确值？</strong> 它擅长趋势，不擅长单点读数；精确值交给 hover、标签或 HTML 指标卡。</li><li><strong>Q：3D 饼图能不能只当装饰？</strong> 可以，但真实占比必须另放一张 2D 图或图例里，主图表别让它承担读数。</li><li><strong>Q：颜色和 ㉔ 有什么关系？</strong> 色板值默认按 sRGB 解释，渲染时解码到线性空间；颜色贴图要解码，数据贴图不要解码。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>为什么 3D 柱状图的柱子必须从 0 起算？如果数据差距太小，应该怎么办？</li><li>柱状、散点、曲面各自最擅长回答什么问题？各举一个不该用它的场景。</li><li>分类色、连续色、发散色分别编码什么？各说一条使用纪律。</li></ol><details><summary>答案</summary><ol><li>柱子的长度只有在同一起点、同一比例尺下才与数值成正比；抬高基线会放大视觉差距，让读者读出错误的倍数关系。差距太小时，应改用差值/增长率、对数刻度并明确标注，或直接在指标卡里给出精确值，而不是截断基线。</li><li>柱状擅长比大小与排名，不适合表达相关关系；散点擅长看相关、聚类与离群点，不适合精确报出单个类别的排名；曲面擅长看整体趋势与波峰波谷，不适合单点精确读数。3D 饼图则不适合任何占比比较。</li><li>分类色编码无序的离散类别，纪律是控制在六到八种并配标签；连续色编码有序数值，纪律是明度或色相单向递进，避免彩虹色；发散色编码围绕中点的偏离，纪律是中点用中性色、两端用对立色相并标明方向。</li></ol></details>',22)])])}const p=a(o,[["render",i]]);export{b as __pageData,p as default};
